(() => {
  const dlg = document.querySelector('[data-testid=print-dialog]') || document.querySelector('[role=dialog]') || document.body
  const text = dlg.innerText || ''
  const buttons = [...dlg.querySelectorAll('button')].map(b => (b.textContent || '').trim())
  const want = {
    groupPrinter: '打印机', groupRange: '打印范围', groupSettings: '设置',
    fName: '名称', fPort: '位置', fPrinterProps: '打印机属性',
    fQty: '打印数量', fCopy: '单签拷贝', fStartRecord: '启始记录', fCurrentOnly: '只打印数据表中当前记录行的数据',
    fUpdateVars: '打印后更新变量数据', fBorder: '打印标签边框', fRotate180: '旋转180度输出',
    startLabel: '选择起始标签', autoTrack: '自动跟踪起始标签位置', advanced: '高级选项'
  }
  const present = {}
  for (const [k, v] of Object.entries(want)) present[k] = text.includes(v)
  const btnWant = { preview: '预览', print: '打印', testPrint: '测试打印', cancel: '取消', help: '帮助' }
  const btnPresent = {}
  for (const [k, v] of Object.entries(btnWant)) btnPresent[k] = buttons.some(b => b === v || b.includes(v))
  const missing = [...Object.entries(present).filter(([, v]) => !v).map(([k]) => k),
                   ...Object.entries(btnPresent).filter(([, v]) => !v).map(([k]) => 'btn:' + k)]
  return JSON.stringify({ missingCount: missing.length, missing, present, buttons })
})()
